  var yTop = 35, yBot = 535, maxOff = 250;                 // visible screen span
  var AMP = 165;                                           // intensity amplitude (px)

  var GRAY = '#8c8c8c', TAN = '#c9a26f', RED = '#d1495b', HL = '#e8730c';

  var state = { a: 1414, lam: 500 };
  var revealTheta1 = false;
  var selM = null;   // signed order, e.g. +1, -2

  // ---- helpers -----------------------------------------------------------
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    return t;
  }
  function txt(g, s, x, y, size, anchor, color, italic) {
    var t = g.text(s).font({ family: 'sans-serif', size: size || 13, anchor: anchor || 'start' })
      .fill(color || '#222').attr({ x: x, y: y, 'dominant-baseline': 'middle' });
    if (italic) t.attr('font-style', 'italic');
    return t;
  }
  function arrowHead(g, x, y, ang, s, color) {
    var a1 = ang + Math.PI * 0.85, a2 = ang - Math.PI * 0.85;
    g.polygon([x + ',' + y,
    (x + s * Math.cos(a1)) + ',' + (y + s * Math.sin(a1)),
    (x + s * Math.cos(a2)) + ',' + (y + s * Math.sin(a2))].join(' ')).fill(color);
  }
  function fmtA(d) {
    return (Math.abs(d - Math.round(d)) < 0.05) ? d.toFixed(0) + '°' : d.toFixed(1) + '°';
  }
  var STOPS = [[400, [106, 63, 160]], [450, [43, 79, 208]], [500, [26, 143, 160]],
  [550, [74, 160, 42]], [600, [217, 160, 23]], [650, [204, 47, 47]], [700, [176, 32, 32]]];
  function wlColor(w) {
    for (var i = 0; i < STOPS.length - 1; i++) {
      if (w <= STOPS[i + 1][0]) {
        var t = (w - STOPS[i][0]) / (STOPS[i + 1][0] - STOPS[i][0]), c = [];
        for (var k = 0; k < 3; k++) c.push(Math.round(STOPS[i][1][k] + t * (STOPS[i + 1][1][k] - STOPS[i][1][k])));
        return 'rgb(' + c.join(',') + ')';
      }
    }
    return 'rgb(176,32,32)';
  }
  function intensity(y, a, lam) {
    var off = y - cy, th = Math.atan2(off, L), s = Math.sin(th);
    var u = Math.PI * a * s / lam;
    if (Math.abs(u) < 1e-7) return 1;
    var v = Math.sin(u) / u;
    return v * v;
  }
  function curveXat(y, a, lam) { return screenX + AMP * intensity(y, a, lam); }
  function arcPath(r, th) {
    var x0 = cx + r, y0 = cy, x1 = cx + r * Math.cos(th), y1 = cy - r * Math.sin(th);
    return 'M ' + x0 + ' ' + y0 + ' A ' + r + ' ' + r + ' 0 0 0 ' + x1 + ' ' + y1;
  }

  // ---- static scene ------------------------------------------------------
  var gStatic = draw.group();
  var gDyn = draw.group();

  // barrier
  gStatic.rect(8, 155).move(cx - 4, 118).fill(TAN);
  gStatic.rect(8, 155).move(cx - 4, 297).fill(TAN);
  // slit-width double arrow
  gStatic.line(137, 273, 160, 273).stroke({ color: '#222', width: 1 });
  gStatic.line(137, 297, 160, 297).stroke({ color: '#222', width: 1 });
  gStatic.line(148, 273, 148, 297).stroke({ color: '#222', width: 1.4 });
  arrowHead(gStatic, 148, 272, -Math.PI / 2, 7, '#222');
  arrowHead(gStatic, 148, 298, Math.PI / 2, 7, '#222');
  // curved arrow to label 'a'
  gStatic.path('M 66 230 Q 108 228 140 262').fill('none').stroke({ color: '#222', width: 1.3 });
  arrowHead(gStatic, 142, 265, Math.atan2(0.72, 0.69), 7, '#222');
  halo(txt(gStatic, 'a', 54, 224, 17, 'middle', '#222', true));
  // screen
  gStatic.line(screenX, 30, screenX, 540).stroke({ color: '#8a8a8a', width: 2 });
  halo(txt(gStatic, 'Screen', screenX, 20, 14, 'middle', '#222'));

  // ---- dynamic scene -----------------------------------------------------
  function rayGeom(off) {                       // off = |vertical offset| at screen
    if (off <= maxOff) return { x: screenX, o: off, hits: true };
    return { x: cx + L * maxOff / off, o: maxOff, hits: false };
  }

  function render() {
    gDyn.clear();
    var a = state.a, lam = state.lam;
    var ang = [null, null];
    for (var m = 1; m <= 2; m++) {
      var s = m * lam / a;
      ang[m - 1] = (s < 1) ? Math.asin(s) : null;
    }

    // central axis
    gDyn.line(cx, cy, screenX, cy).stroke({ color: GRAY, width: 1, dasharray: '6,5' });

    // fan of dashed rays + nulls
    for (var mi = 1; mi <= 2; mi++) {
      var th = ang[mi - 1];
      if (th === null) continue;
      var off = L * Math.tan(th);
      var ge = rayGeom(off);
      for (var si = -1; si <= 1; si += 2) {
        (function (m, sign, th, ge) {
          var sel = (selM === sign * m);
          var ex = ge.x, ey = cy - sign * ge.o;
          var col = sel ? HL : GRAY;
          gDyn.line(cx, cy, ex, ey).stroke({
            color: col, width: sel ? 2.2 : 1,
            dasharray: sel ? '7,4' : '6,5'
          });
          var hit = gDyn.line(cx, cy, ex, ey).stroke({ color: '#000', width: 14, opacity: 0 })
            .css('cursor', 'pointer');
          var lbl = 'm = ' + (sign > 0 ? '+' : '−') + m + '   θ' + (m === 1 ? '₁' : '₂') +
            ' = ' + fmtA(th * 180 / Math.PI) + '  (a·sinθ = ' + m + 'λ)';
          hit.on('mousemove', function (e) { showTooltip(lbl, e); })
            .on('mouseleave', hideTooltip)
            .on('click', function () {
              selM = sel ? null : sign * m;
              revealTheta1 = true;
              render();
              if (selM !== null) {
                showPopup('Dark fringe, order m = ' + (sign > 0 ? '+' : '−') + m,
                  'This ray leaves the slit at θ = ' + fmtA(th * 180 / Math.PI) +
                  ', the angle that satisfies a·sinθ = ' + m + 'λ with a = ' + Math.round(state.a) +
                  ' nm and λ = ' + Math.round(state.lam) + ' nm. Wavelets from paired points across the slit ' +
                  'arrive exactly out of phase in this direction, so the red intensity curve collapses to zero ' +
                  'precisely where this dashed line meets the screen.');
              }
            });
          // null marker on screen
          if (ge.hits) {
            var dot = gDyn.circle(sel ? 10 : 8).center(screenX, ey)
              .fill(sel ? HL : '#fff').stroke({ color: sel ? HL : '#777', width: 1.4 })
              .css('cursor', 'pointer');
            dot.on('mousemove', function (e) { showTooltip('Zero of intensity — ' + lbl, e); })
              .on('mouseleave', hideTooltip)
              .on('click', function () { selM = sel ? null : sign * m; revealTheta1 = true; render(); });
            var badge = sel
              ? ('m = ' + (sign > 0 ? '+' : '−') + m + ' · θ = ' + fmtA(th * 180 / Math.PI))
              : ('m = ' + (sign > 0 ? '+' : '−') + m);
            halo(txt(gDyn, badge, screenX - 12, ey - (sign > 0 ? 11 : -11), 11.5, 'end',
              sel ? HL : '#555'));
          }
        })(mi, si, th, ge);
      }
    }

    // intensity curve (drawn sideways along the screen)
    var pts = [];
    for (var y = yTop; y <= yBot; y += 1) pts.push(curveXat(y, a, lam).toFixed(1) + ',' + y);
    var poly = gDyn.polyline(pts.join(' ')).fill('none')
      .stroke({ color: RED, width: 2, linejoin: 'round', linecap: 'round' }).css('cursor', 'pointer');
    poly.on('mousemove', function (e) { showTooltip('I(θ) = I₀ [sin u / u]², u = π a sinθ / λ', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Intensity on the screen',
          'Brightness is plotted sideways: the horizontal excursion to the right of the screen line is I(θ) = I₀[sin u / u]² with u = π a sinθ / λ. ' +
          'Its zeros sit exactly at the dashed-ray directions, because u = mπ is the same statement as a·sinθ = mλ. ' +
          'The whole pattern’s angular size therefore depends only on the ratio λ/a.');
      });

    // arrow + label for the intensity curve
    var ty = 470, tx = curveXat(ty, a, lam) + 7;
    gDyn.path('M 578 506 Q 540 500 ' + tx.toFixed(1) + ' ' + ty).fill('none').stroke({ color: '#222', width: 1.3 });
    arrowHead(gDyn, tx, ty, Math.atan2(-0.55, -0.83), 7, '#222');
    halo(txt(gDyn, 'Intensity', 600, 520, 13.5, 'middle', '#222'));
    halo(txt(gDyn, 'on screen', 600, 537, 13.5, 'middle', '#222'));

    // angle arcs
    if (ang[1] !== null) {
      var r2 = 112, t2 = ang[1];
      gDyn.path(arcPath(r2, t2)).fill('none').stroke({ color: '#333', width: 1.1 });
      var p2 = [cx + (r2 + 11) * Math.cos(t2 / 2), cy - (r2 + 11) * Math.sin(t2 / 2)];
      halo(txt(gDyn, 'θ₂ = ' + fmtA(t2 * 180 / Math.PI), p2[0], p2[1], 14, 'start',
        (selM === 2 || selM === -2) ? HL : '#111', false));
    }
    if (ang[0] !== null) {
      var r1 = 74, t1 = ang[0];
      gDyn.path(arcPath(r1, t1)).fill('none').stroke({ color: '#333', width: 1.1 });
      var p1 = [cx + (r1 + 11) * Math.cos(t1 / 2), cy - (r1 + 11) * Math.sin(t1 / 2)];
      halo(txt(gDyn, 'θ₁ = ' + (revealTheta1 ? fmtA(t1 * 180 / Math.PI) : '?'), p1[0], p1[1], 14, 'start',
        (selM === 1 || selM === -1) ? HL : '#111', false));
    }

    // incoming light arrow (colour tracks λ)
    var wc = wlColor(lam);
    gDyn.line(74, cy, 150, cy).stroke({ color: wc, width: 2.6 });
    arrowHead(gDyn, 156, cy, 0, 8, wc);
    halo(txt(gDyn, 'λ', 76, 268, 16, 'middle', wc, true));

    // readout panel
    gDyn.rect(146, 92).move(10, 14).fill('#ffffff').opacity(0.86)
      .stroke({ color: '#dcdfe3', width: 1 }).radius(4);
    var rows = [
      'a = ' + Math.round(a) + ' nm',
      'λ = ' + Math.round(lam) + ' nm',
      'a/λ = ' + (a / lam).toFixed(2),
      'θ₁ = ' + (ang[0] === null ? 'none (sinθ>1)' : (revealTheta1 ? fmtA(ang[0] * 180 / Math.PI) : '?')),
      'θ₂ = ' + (ang[1] === null ? 'none (sinθ>1)' : fmtA(ang[1] * 180 / Math.PI))
    ];
    for (var i = 0; i < rows.length; i++) txt(gDyn, rows[i], 20, 28 + i * 16, 11.5, 'start', '#333');
  }

  // ---- demo steps --------------------------------------------------------
  var steps = [
    {
      title: '1. The given configuration',
      narration: 'Light of wavelength λ passes a slit of width a and fans out into five marked directions. The outermost upper ray is the second minimum at θ₂ = 45°; the inner one is the unknown θ₁.',
      state: { slitWidth: 1414, wavelength: 500 }, sel: null, reveal: false
    },
    {
      title: '2. Rays meet the nulls',
      narration: 'Click any dashed ray: it lights up together with the point where the red curve pinches to zero. Every dashed line points at a dark fringe, never a bright one.',
      state: { slitWidth: 1414, wavelength: 500 }, sel: 2, reveal: false
    },
    {
      title: '3. Solve for θ₁',
      narration: 'With a·sin45° = 2λ fixing a ≈ 2.83λ, the m = 1 condition a·sinθ₁ = λ gives sinθ₁ = 0.354, so θ₁ ≈ 20.7° — read it off the inner arc.',
      state: { slitWidth: 1414, wavelength: 500 }, sel: 1, reveal: true
    },
    {
      title: '4. Narrow the slit',
      narration: 'Shrink a while λ stays fixed: the dashed rays swing outward and the central lobe balloons. A smaller opening produces a wider diffraction pattern (m = 2 can even vanish).',
      state: { slitWidth: 800, wavelength: 500 }, sel: null, reveal: true
    },
    {
      title: '5. Widen the slit',
      narration: 'Open the slit up and the rays collapse toward the axis, the central peak narrows, and the light behaves more like a straight beam.',
      state: { slitWidth: 2800, wavelength: 500 }, sel: null, reveal: true
    },
    {
      title: '6. Change the colour',
      narration: 'Back at the original width, switch from blue-green to red light: longer λ pushes every null to a larger angle. Only the ratio λ/a controls the pattern.',
      state: { slitWidth: 1414, wavelength: 680 }, sel: null, reveal: true
    }
  ];
  var cur = 0;

  function setSlider(id, v) {
    var inp = document.getElementById(id + 'Input');
    var out = document.getElementById(id + 'Val');
    if (inp) inp.value = v;
    if (out) out.value = v;
  }
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    setSlider('slitWidth', st.state.slitWidth);
    setSlider('wavelength', st.state.wavelength);
    state.a = st.state.slitWidth;
    state.lam = st.state.wavelength;
    revealTheta1 = !!st.reveal;
    selM = st.sel;
    document.getElementById('demoNarration').innerHTML = '<b>' + st.title + '</b><br>' + st.narration;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    render();
  }

  // ---- exposed handlers --------------------------------------------------
  window.update_slitWidth = function (v) { state.a = v; revealTheta1 = true; render(); };
  window.update_wavelength = function (v) { state.lam = v; revealTheta1 = true; render(); };
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };
  window.resetFigure = function () { applyStep(0); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
