  <input id="wavelengthInput" type="range" min="400" max="700" step="5" value="500"
    oninput="document.getElementById('wavelengthVal').value=this.value;update_wavelength(+this.value)"></label>
<label><input id="annotInput" type="checkbox" onchange="toggle_annot(this.checked)"> Order labels &amp; readout</label>
<span style="display:flex;gap:6px;align-items:center;margin-top:4px">
  <button onclick="prevStep()">◀</button><span id="stepLabel">1 / 6</span><button onclick="nextStep()">▶</button>
  <button onclick="resetFigure()" style="margin-left:auto">↺</button></span>
<p id="demoNarration" style="margin:0;font-size:11px;line-height:1.45"></p>
<span style="font-size:10px;color:#666;line-height:1.4">Click a dashed ray (or its landing point on the screen) to lock the geometric angle θ<sub>m</sub> to the matching zero of the red intensity curve. Hover anything for a quick label.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var container = document.getElementById('container');
  var draw = SVG().addTo(container).size('100%', '100%');
  var W = 680, H = 600;
  draw.viewbox(0, 0, W, H);

  // ---- geometry ----------------------------------------------------------
  var cx = 170, cy = 290, L = 190, screenX = cx + L;   // slit -> screen
  var yTop = 48, yBot = 532, maxOff = cy - yTop;       // visible screen span
  var AMP = 170;                                       // intensity excursion (px)
  var GAM = 1 / 3;                                     // brightness compression (keeps side lobes visible)

  var GRAY = '#8c8c8c', TAN = '#c9a26f', RED = '#cc4455', HL = '#e8730c';

  var state = { a: 1414, lam: 500 };
  var revealTheta1 = false;
  var showAnnot = false;
  var selM = null;   // signed order, e.g. +1, -2

  // ---- helpers -----------------------------------------------------------
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    return t;
  }
  function txt(g, s, x, y, size, anchor, color, italic) {
    var t = g.text(s).font({ family: 'sans-serif', size: size || 13, anchor: anchor || 'start' })
      .fill(color || '#222').attr({ x: x, y: y, 'dominant-baseline': 'middle' });
    if (italic) t.attr('font-style', 'italic');
    return t;
  }
  function arrowHead(g, x, y, ang, s, color) {
    var a1 = ang + Math.PI * 0.85, a2 = ang - Math.PI * 0.85;
    g.polygon([x + ',' + y,
    (x + s * Math.cos(a1)) + ',' + (y + s * Math.sin(a1)),
    (x + s * Math.cos(a2)) + ',' + (y + s * Math.sin(a2))].join(' ')).fill(color);
  }
  function fmtA(d) {
    return (Math.abs(d - Math.round(d)) < 0.05) ? d.toFixed(0) + '°' : d.toFixed(1) + '°';
  }
  var STOPS = [[400, [86, 60, 170]], [450, [40, 80, 205]], [500, [22, 140, 160]],
  [550, [70, 158, 45]], [600, [214, 158, 24]], [650, [202, 50, 48]], [700, [172, 30, 30]]];
  function wlColor(w) {
    for (var i = 0; i < STOPS.length - 1; i++) {
      if (w <= STOPS[i + 1][0]) {
        var t = (w - STOPS[i][0]) / (STOPS[i + 1][0] - STOPS[i][0]), c = [];
        for (var k = 0; k < 3; k++) c.push(Math.round(STOPS[i][1][k] + t * (STOPS[i + 1][1][k] - STOPS[i][1][k])));
        return 'rgb(' + c.join(',') + ')';
      }
    }
    return 'rgb(172,30,30)';
  }
  function intensity(y, a, lam) {
    var off = y - cy, s = off / Math.sqrt(off * off + L * L);
    var u = Math.PI * a * s / lam;
    if (Math.abs(u) < 1e-7) return 1;
    var v = Math.sin(u) / u;
    return v * v;
  }
  // brightness drawn with a mild gamma so the small side lobes stay clearly wavy
  function curveXat(y, a, lam) {
    return screenX + AMP * Math.pow(intensity(y, a, lam), GAM);
  }
  function arcPath(r, th) {
    var x0 = cx + r, y0 = cy, x1 = cx + r * Math.cos(th), y1 = cy - r * Math.sin(th);
    return 'M ' + x0 + ' ' + y0 + ' A ' + r + ' ' + r + ' 0 0 0 ' + x1 + ' ' + y1;
  }

  // ---- static scene ------------------------------------------------------
  var gStatic = draw.group();
  var gDyn = draw.group();

  // barrier (two thick tan bars with a narrow gap = the slit)
  var gapTop = 278, gapBot = 302;
  var bar1 = gStatic.rect(8, 128).move(cx - 4, 150).fill(TAN);
  var bar2 = gStatic.rect(8, 128).move(cx - 4, 302).fill(TAN);
  [bar1, bar2].forEach(function (b) {
    b.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Opaque barrier', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The barrier and its slit',
          'Everything is blocked except the narrow gap of width a. Huygens wavelets spreading from every point inside that gap are what interfere to build the pattern on the screen.');
      });
  });

  // slit-width double arrow, drawn inside the gap itself
  var gSlit = gStatic.group().css('cursor', 'pointer');
  gSlit.line(cx - 12, gapTop, cx + 12, gapTop).stroke({ color: '#222', width: 1 });
  gSlit.line(cx - 12, gapBot, cx + 12, gapBot).stroke({ color: '#222', width: 1 });
  gSlit.line(cx, gapTop + 1, cx, gapBot - 1).stroke({ color: '#222', width: 1.4 });
  arrowHead(gSlit, cx, gapTop + 1, -Math.PI / 2, 6.5, '#222');
  arrowHead(gSlit, cx, gapBot - 1, Math.PI / 2, 6.5, '#222');
  gSlit.rect(30, 34).move(cx - 15, gapTop - 5).fill('#000').opacity(0);
  gSlit.on('mousemove', function (e) { showTooltip('Slit width a = ' + Math.round(state.a) + ' nm', e); })
    .on('mouseleave', hideTooltip);

  // curved arrow out to the italic label 'a'
  gStatic.path('M 66 240 Q 106 250 144 271').fill('none').stroke({ color: '#222', width: 1.3 });
  arrowHead(gStatic, 147, 273, Math.atan2(0.55, 0.84), 7, '#222');
  halo(txt(gStatic, 'a', 54, 232, 17, 'middle', '#222', true));

  // screen
  gStatic.line(screenX, 36, screenX, 560).stroke({ color: '#808080', width: 2 });
  halo(txt(gStatic, 'Screen', screenX, 26, 14, 'middle', '#222'));

  // ---- dynamic scene -----------------------------------------------------
  function rayEnd(off) {
    if (off <= maxOff) return { x: screenX, o: off, hits: true };
    return { x: cx + L * maxOff / off, o: maxOff, hits: false };
  }

  function render() {
    gDyn.clear();
    var a = state.a, lam = state.lam;
    var ang = [];
    for (var m = 1; m <= 2; m++) {
      var s = m * lam / a;
      ang.push(s < 1 ? Math.asin(s) : null);
    }

    // central axis (θ = 0)
    var axis = gDyn.line(cx, cy, screenX, cy).stroke({ color: GRAY, width: 1, dasharray: '6,5' });
    gDyn.line(cx, cy, screenX, cy).stroke({ color: '#000', width: 12, opacity: 0 })
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('θ = 0 — central maximum', e); })
      .on('mouseleave', hideTooltip);

    // fan of dashed minima rays
    for (var mi = 1; mi <= 2; mi++) {
      var th = ang[mi - 1];
      if (th === null) continue;
      var off = L * Math.tan(th);
      var ge = rayEnd(off);
      for (var si = -1; si <= 1; si += 2) {
        (function (m, sign, th, ge) {
          var sel = (selM === sign * m);
          var ex = ge.x, ey = cy - sign * ge.o;
          gDyn.line(cx, cy, ex, ey).stroke({
            color: sel ? HL : GRAY, width: sel ? 2.2 : 1, dasharray: sel ? '7,4' : '6,5'
          });
          var lbl = 'm = ' + (sign > 0 ? '+' : '−') + m + '   θ' + (m === 1 ? '₁' : '₂') +
            ' = ' + fmtA(th * 180 / Math.PI) + '   (a·sinθ = ' + m + 'λ)';
          function pick() {
            selM = sel ? null : sign * m;
            revealTheta1 = true;
            if (selM !== null) showAnnot = true;
            syncAnnotBox();
            render();
          }
          gDyn.line(cx, cy, ex, ey).stroke({ color: '#000', width: 14, opacity: 0 })
            .css('cursor', 'pointer')
            .on('mousemove', function (e) { showTooltip(lbl, e); })
            .on('mouseleave', hideTooltip)
            .on('click', function () {
              var was = sel;
              pick();
              if (!was) {
                showPopup('Dark fringe, order m = ' + (sign > 0 ? '+' : '−') + m,
                  'This ray leaves the slit at θ = ' + fmtA(th * 180 / Math.PI) +
                  ', the angle satisfying a·sinθ = ' + m + 'λ for a = ' + Math.round(state.a) +
                  ' nm and λ = ' + Math.round(state.lam) + ' nm. Wavelets from paired points across the slit ' +
                  'arrive exactly out of phase in this direction, so the red intensity curve collapses to zero ' +
                  'precisely where this dashed line meets the screen.');
              }
            });
          if (ge.hits && (showAnnot || sel)) {
            var dot = gDyn.circle(sel ? 10 : 7).center(screenX, ey)
              .fill(sel ? HL : '#fff').stroke({ color: sel ? HL : '#888', width: 1.2 })
              .css('cursor', 'pointer');
            dot.on('mousemove', function (e) { showTooltip('Zero of intensity — ' + lbl, e); })
              .on('mouseleave', hideTooltip)
              .on('click', pick);
            var badge = sel
              ? ('m = ' + (sign > 0 ? '+' : '−') + m + ' · θ = ' + fmtA(th * 180 / Math.PI))
              : ('m = ' + (sign > 0 ? '+' : '−') + m);
            halo(txt(gDyn, badge, screenX - 13, ey - (sign > 0 ? 12 : -12), 11.5, 'end',
              sel ? HL : '#555'));
          }
        })(mi, si, th, ge);
      }
    }

    // red intensity curve, drawn sideways along the screen
    var pts = [];
    for (var y = yTop; y <= yBot; y += 1) pts.push(curveXat(y, a, lam).toFixed(1) + ',' + y);
    gDyn.polyline(pts.join(' ')).fill('none')
      .stroke({ color: RED, width: 2, linejoin: 'round', linecap: 'round' })
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('I(θ) = I₀ [sin u / u]²,  u = π a sinθ / λ', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Intensity on the screen',
          'Brightness is plotted sideways: the excursion to the right of the screen line is I(θ) = I₀[sin u / u]² with u = π a sinθ / λ (drawn with a mild compression so the small side lobes stay visible). ' +
          'Its zeros sit exactly at the dashed-ray directions, because u = mπ is the same statement as a·sinθ = mλ. ' +
          'The pattern’s angular size therefore depends only on the ratio λ/a.');
      });

    // short curved callout to the red curve near the bottom
    var ty = 516, tx = curveXat(ty, a, lam) + 4;
    gDyn.path('M 446 552 Q 412 549 ' + tx.toFixed(1) + ' ' + (ty + 4)).fill('none')
      .stroke({ color: '#222', width: 1.3 });
    arrowHead(gDyn, tx, ty + 2, Math.atan2(-0.86, -0.5), 7, '#222');
    halo(txt(gDyn, 'Intensity', 482, 557, 13.5, 'middle', '#222'));
    halo(txt(gDyn, 'on screen', 482, 574, 13.5, 'middle', '#222'));

    // angle arcs and their labels
    if (ang[1] !== null) {
      var t2 = ang[1];
      gDyn.path(arcPath(100, t2)).fill('none').stroke({ color: '#333', width: 1.1 });
      var b2 = t2 * 0.72, R2 = 150;
      halo(txt(gDyn, 'θ₂ = ' + fmtA(t2 * 180 / Math.PI),
        cx + R2 * Math.cos(b2), cy - R2 * Math.sin(b2), 14, 'middle',
        (selM === 2 || selM === -2) ? HL : '#111'));
    }
    if (ang[0] !== null) {
      var t1 = ang[0];
      gDyn.path(arcPath(68, t1)).fill('none').stroke({ color: '#333', width: 1.1 });
      var b1 = t1 * 0.5, R1 = 130;
      halo(txt(gDyn, 'θ₁ = ' + (revealTheta1 ? fmtA(t1 * 180 / Math.PI) : '?'),
        cx + R1 * Math.cos(b1), cy - R1 * Math.sin(b1), 14, 'middle',
        (selM === 1 || selM === -1) ? HL : '#111'));
    }

    // incoming light (colour tracks λ) — kept short so it clears the slit arrow
    var wc = wlColor(lam);
    gDyn.line(72, cy, 149, cy).stroke({ color: wc, width: 2.6 });
    arrowHead(gDyn, 155, cy, 0, 7.5, wc);
    var lamT = halo(txt(gDyn, 'λ', 80, 272, 16, 'middle', wc, true));
    lamT.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Incident wavelength λ = ' + Math.round(lam) + ' nm', e); })
      .on('mouseleave', hideTooltip);

    // compact readout (optional)
    if (showAnnot) {
      gDyn.rect(150, 92).move(10, 14).fill('#ffffff').opacity(0.88)
        .stroke({ color: '#dcdfe3', width: 1 }).radius(4);
      var rows = [
        'a = ' + Math.round(a) + ' nm',
        'λ = ' + Math.round(lam) + ' nm',
        'a/λ = ' + (a / lam).toFixed(2),
        'θ₁ = ' + (ang[0] === null ? 'none (sinθ>1)' : (revealTheta1 ? fmtA(ang[0] * 180 / Math.PI) : '?')),
        'θ₂ = ' + (ang[1] === null ? 'none (sinθ>1)' : fmtA(ang[1] * 180 / Math.PI))
      ];
      for (var i = 0; i < rows.length; i++) txt(gDyn, rows[i], 20, 28 + i * 16, 11.5, 'start', '#333');
    }
  }

  // ---- demo steps --------------------------------------------------------
  var steps = [
    {
      title: '1. The given configuration',
      narration: 'Light of wavelength λ passes a slit of width a and fans out into five marked directions. The outermost upper ray is the second minimum at θ₂ = 45°; the inner one is the unknown θ₁.',
      a: 1414, lam: 500, sel: null, reveal: false, annot: false
    },
    {
      title: '2. Rays meet the nulls',
      narration: 'Click any dashed ray: it lights up together with the point where the red curve pinches to zero. Every dashed line points at a dark fringe, never a bright one.',
      a: 1414, lam: 500, sel: 2, reveal: false, annot: true
    },
    {
      title: '3. Solve for θ₁',
      narration: 'With a·sin45° = 2λ fixing a ≈ 2.83λ, the m = 1 condition a·sinθ₁ = λ gives sinθ₁ = 0.354, so θ₁ ≈ 20.7° — read it off the inner arc.',
      a: 1414, lam: 500, sel: 1, reveal: true, annot: true
    },
    {
      title: '4. Narrow the slit',
      narration: 'Shrink a while λ stays fixed: the dashed rays swing outward and the central lobe balloons. A smaller opening gives a wider pattern — here m = 2 disappears entirely (sinθ₂ > 1).',
      a: 800, lam: 500, sel: null, reveal: true, annot: true
    },
    {
      title: '5. Widen the slit',
      narration: 'Open the slit up and the rays collapse toward the axis, the central peak narrows, and the light behaves more like a straight beam.',
      a: 2800, lam: 500, sel: null, reveal: true, annot: true
    },
    {
      title: '6. Change the colour',
      narration: 'Back at the original width, switch from blue-green to red light: longer λ pushes every null to a larger angle. Only the ratio λ/a controls the pattern.',
      a: 1414, lam: 680, sel: null, reveal: true, annot: true
    }
  ];
  var cur = 0;

  function setSlider(id, v) {
    var inp = document.getElementById(id + 'Input');
    var out = document.getElementById(id + 'Val');
    if (inp) inp.value = v;
    if (out) out.value = v;
  }
  function syncAnnotBox() {
    var box = document.getElementById('annotInput');
    if (box) box.checked = showAnnot;
  }
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    setSlider('slitWidth', st.a);
    setSlider('wavelength', st.lam);
    state.a = st.a; state.lam = st.lam;
    revealTheta1 = !!st.reveal;
    showAnnot = !!st.annot;
    selM = st.sel;
    syncAnnotBox();
    document.getElementById('demoNarration').innerHTML = '<b>' + st.title + '</b><br>' + st.narration;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    render();
  }

  // ---- exposed handlers --------------------------------------------------
  window.update_slitWidth = function (v) { state.a = v; revealTheta1 = true; render(); };
  window.update_wavelength = function (v) { state.lam = v; revealTheta1 = true; render(); };
  window.toggle_annot = function (on) { showAnnot = on; render(); };
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };
  window.resetFigure = function () { applyStep(0); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

